// UART_apb checker (generated by scripts/apb/gen_apb.py; do not edit).
// Register model held as an array of words, updated from the APB pins and
// the core's outputs; it predicts PRDATA on every read, PSLVERR, PREADY, irq
// and every core input the wrapper drives. FC: every word read and written,
// every interrupt bit set / cleared / masked / raising irq, stream events,
// strobes, unmapped and misaligned accesses, back-to-back transfers.
`include "cov_macros.svh"
module UART_apb_sva (
  input logic PCLK, PRESETN, PSEL, PENABLE, PWRITE,
  input logic [11:0] PADDR,
  input logic [31:0] PWDATA,
  input logic [3:0] PSTRB,
  input logic [31:0] PRDATA,
  input logic PREADY, PSLVERR, irq,
  input logic [7:0] c_tx_data,
  input logic [7:0] c_rx_data,
  input logic  c_tx_valid,
  input logic  c_tx_ready,
  input logic  c_rx_valid,
  input logic  c_irq
);
  `COV_CLOCKING(PCLK, !PRESETN)
  wire        m_wr  = PSEL && PENABLE && PWRITE;
  wire        m_rd  = PSEL && PENABLE && !PWRITE;
  wire        m_map = PADDR[1:0] == 2'b00 && (PADDR >> 2) < 7;
  wire [9:0] m_idx = PADDR[11:2];
  wire [31:0] m_be  = {{8{PSTRB[3]}}, {8{PSTRB[2]}}, {8{PSTRB[1]}}, {8{PSTRB[0]}}};
  logic [31:0] m_w [0:6];          // model of every stored word
  logic [4:0] m_set;                // interrupt bits set this clock
  logic m_state_TXDATA;          // full / valid pulse / available
  logic m_state_RXDATA;          // full / valid pulse / available

  always_comb begin
    m_set = '0;
    if (c_irq) m_set[0] = 1'b1;
    if (m_state_TXDATA && c_tx_ready) m_set[1] = 1'b1;
    if (m_wr && m_map && (m_idx == 5) && m_state_TXDATA) m_set[2] = 1'b1;
    if (c_rx_valid && !m_state_RXDATA) m_set[3] = 1'b1;
    if (c_rx_valid && m_state_RXDATA && (m_rd && m_map && m_idx == 6)) m_set[3] = 1'b1;
    if (c_rx_valid && m_state_RXDATA && !(m_rd && m_map && m_idx == 6)) m_set[4] = 1'b1;
  end

  always_ff @(posedge PCLK or negedge PRESETN) begin
    if (!PRESETN) begin
      m_w[0] <= 32'h0;
      m_w[1] <= 32'h0;
      m_w[2] <= 32'h0;
      m_w[3] <= 32'h0;
      m_w[4] <= 32'h0;
      m_w[5] <= 32'h0;
      m_w[6] <= 32'h0;
      m_state_TXDATA <= 0;
      m_state_RXDATA <= 0;
    end else begin
      m_w[1] <= (m_w[1] & ~((m_wr && m_map && m_idx == 1) ? PWDATA & m_be : 0)) | 32'(m_set);
      if (m_wr && m_map && m_idx == 2) m_w[2] <= ((m_w[2] & ~m_be) | (PWDATA & m_be)) & 32'h1F;
      if (m_wr && m_map && m_idx == 4) m_w[4] <= ((m_w[4] & ~m_be) | (PWDATA & m_be)) & 32'hFFFFFFFF;
      if (m_wr && m_map && m_idx == 5 && !m_state_TXDATA) m_w[5] <= ((m_w[5] & ~m_be) | (PWDATA & m_be)) & 32'hFF;
      if (m_wr && m_map && m_idx == 5 && !m_state_TXDATA) m_state_TXDATA <= 1;
      if (m_state_TXDATA && c_tx_ready) m_state_TXDATA <= 0;
      if (c_rx_valid && (!m_state_RXDATA || (m_rd && m_map && m_idx == 6))) begin
        m_w[6] <= (32'(c_rx_data[7:0]) << 0);
        m_state_RXDATA <= 1;
      end else if ((m_rd && m_map && m_idx == 6)) m_state_RXDATA <= 0;
    end
  end

  function automatic logic [31:0] m_read(input logic [9:0] i);
    case (i)
      0: return 32'h55410200;
      1: return m_w[1];
      2: return m_w[2];
      3: return 32'({m_state_RXDATA, m_state_TXDATA});
      4: return m_w[4];
      5: return m_w[5];
      6: return m_w[6];
      default: return 0;
    endcase
  endfunction

  // ---------------- assertions ----------------
  `SVA_INV(a_pready_zero_wait, PREADY == (PSEL && PENABLE))
  `SVA_IMP(a_pslverr_decode, PSEL && PENABLE, PSLVERR == !m_map)
  `SVA_IMP(a_read_data, m_rd && m_map, PRDATA == m_read(m_idx))
  `SVA_IMP(a_unmapped_read_zero, m_rd && !m_map, PRDATA == 0)
  `SVA_IMP(a_prdata_zero_outside_read, !m_rd, PRDATA == 0)
  `SVA_INV(a_irq_pin, irq == |(m_w[1][4:0] & m_w[2][4:0]))
  `SVA_INV(a_core_tx_data, c_tx_data == m_w[5][7:0])
  `SVA_INV(a_core_tx_valid, c_tx_valid == m_state_TXDATA)
  `SVA_RST(a_reset_values, !PRESETN, PRDATA == 0 && !irq && c_tx_data == 8'h0 && !c_tx_valid)

  // ---------------- functional coverage ----------------
  `FC(rd_ID, m_rd && m_map && m_idx == 0)
  `FC(wr_ID, m_wr && m_map && m_idx == 0)
  `FC(rd_IRQ_STATUS, m_rd && m_map && m_idx == 1)
  `FC(wr_IRQ_STATUS, m_wr && m_map && m_idx == 1)
  `FC(rd_IRQ_ENABLE, m_rd && m_map && m_idx == 2)
  `FC(wr_IRQ_ENABLE, m_wr && m_map && m_idx == 2)
  `FC(rd_FLAGS, m_rd && m_map && m_idx == 3)
  `FC(wr_FLAGS, m_wr && m_map && m_idx == 3)
  `FC(rd_SCRATCH, m_rd && m_map && m_idx == 4)
  `FC(wr_SCRATCH, m_wr && m_map && m_idx == 4)
  `FC(rd_TXDATA, m_rd && m_map && m_idx == 5)
  `FC(wr_TXDATA, m_wr && m_map && m_idx == 5)
  `FC(rd_RXDATA, m_rd && m_map && m_idx == 6)
  `FC(wr_RXDATA, m_wr && m_map && m_idx == 6)
  `FC(unmapped_read, m_rd && !m_map && PADDR[1:0] == 0)
  `FC(unmapped_write, m_wr && !m_map && PADDR[1:0] == 0)
  `FC(misaligned_read, m_rd && PADDR[1:0] != 0)
  `FC(misaligned_write, m_wr && PADDR[1:0] != 0)
  `FC(partial_strobe_write, m_wr && m_map && PSTRB != 4'h0 && PSTRB != 4'hF)
  `FC(zero_strobe_write, m_wr && m_map && PSTRB == 4'h0)
  `FC(back_to_back, PSEL && PENABLE ##1 PSEL && !PENABLE)
  `FC(idle_between, PSEL && PENABLE ##1 !PSEL)
  `FC(irq_CORE_set, m_set[0])
  `FC(irq_CORE_cleared, m_w[1][0] && m_wr && m_map && m_idx == 1 && PWDATA[0] && PSTRB[0])
  `FC(irq_CORE_masked, m_w[1][0] && !m_w[2][0])
  `FC(irq_CORE_drives_pin, m_w[1][0] && m_w[2][0] && irq)
  `FC(irq_TXDATA_DONE_set, m_set[1])
  `FC(irq_TXDATA_DONE_cleared, m_w[1][1] && m_wr && m_map && m_idx == 1 && PWDATA[1] && PSTRB[0])
  `FC(irq_TXDATA_DONE_masked, m_w[1][1] && !m_w[2][1])
  `FC(irq_TXDATA_DONE_drives_pin, m_w[1][1] && m_w[2][1] && irq)
  `FC(irq_TXDATA_OVF_set, m_set[2])
  `FC(irq_TXDATA_OVF_cleared, m_w[1][2] && m_wr && m_map && m_idx == 1 && PWDATA[2] && PSTRB[0])
  `FC(irq_TXDATA_OVF_masked, m_w[1][2] && !m_w[2][2])
  `FC(irq_TXDATA_OVF_drives_pin, m_w[1][2] && m_w[2][2] && irq)
  `FC(irq_RXDATA_AVAIL_set, m_set[3])
  `FC(irq_RXDATA_AVAIL_cleared, m_w[1][3] && m_wr && m_map && m_idx == 1 && PWDATA[3] && PSTRB[0])
  `FC(irq_RXDATA_AVAIL_masked, m_w[1][3] && !m_w[2][3])
  `FC(irq_RXDATA_AVAIL_drives_pin, m_w[1][3] && m_w[2][3] && irq)
  `FC(irq_RXDATA_OVF_set, m_set[4])
  `FC(irq_RXDATA_OVF_cleared, m_w[1][4] && m_wr && m_map && m_idx == 1 && PWDATA[4] && PSTRB[0])
  `FC(irq_RXDATA_OVF_masked, m_w[1][4] && !m_w[2][4])
  `FC(irq_RXDATA_OVF_drives_pin, m_w[1][4] && m_w[2][4] && irq)
  `FC(TXDATA_handshake, m_state_TXDATA && c_tx_ready)
  `FC(TXDATA_backpressure, m_state_TXDATA && !c_tx_ready)
  `FC(TXDATA_write_while_full, m_wr && m_map && m_idx == 5 && m_state_TXDATA)
  `FC(RXDATA_capture, c_rx_valid && !m_state_RXDATA)
  `FC(RXDATA_overflow, c_rx_valid && m_state_RXDATA && !(m_rd && m_map && m_idx == 6))
  `FC(RXDATA_pop, m_rd && m_map && m_idx == 6 && m_state_RXDATA)
  `FC(RXDATA_read_empty, m_rd && m_map && m_idx == 6 && !m_state_RXDATA)
  `FC(RXDATA_pop_and_capture, c_rx_valid && m_state_RXDATA && m_rd && m_map && m_idx == 6)
  `FC_RST(reset_with_pending_irq, PRESETN && m_w[1] != 0 ##1 !PRESETN)
endmodule

bind UART_apb UART_apb_sva u_apb_sva (.*);
